/bin/bash -lc "python3 - <<'PY'
import numpy as np
p='inputs/protein.shape.q1.pdb'; data={}
with open(p) as f:
 for line in f:
  if line.startswith('ATOM') and line[12:16].strip()=='CA':
   c=line[21]; data.setdefault(c,[]).append([float(line[30:38]),float(line[38:46]),float(line[46:54])])
for c,arr in data.items():
 a=np.array(arr)-np.mean(arr,axis=0)
 u,s,vt=np.linalg.svd(a)
 print(c,'n',len(a),'singular',s.round(1),'axis',vt[0].round(3),'range along axis',[(a@vt[k]).min().round(1),(a@vt[k]).max().round(1)] for k in range(3))
 print('bbox',a.min(0).round(1),a.max(0).round(1))
PY"

